<template>
 <main class="workbench"><header class="wb-head"><div><span class="wb-kicker">HUGGING FACE DATA</span><h1>Hugging Face 数据集</h1><p>查找公开或已授权的静态数据，固定 revision 后预览并导入。已有资产可直接使用其他能力，无需重新采集。</p></div></header><ScenarioPath current="/hf-datasets" />
 <p v-if="error" class="wb-error" role="alert">{{ error }}</p><p v-if="notice" class="wb-success" role="status">{{ notice }}</p>
 <div class="wb-grid"><aside class="wb-panel wb-stack"><h2>查找数据集</h2><form class="wb-stack" @submit.prevent="search()"><label class="wb-label">搜索关键词<input v-model="query" :disabled="busy" /></label><button :disabled="busy">搜索 Hugging Face</button></form><div class="wb-list"><button v-for="item in results" :key="item.repo_id" :disabled="busy || !!pending" @click="choose(item.repo_id)"><strong>{{ item.repo_id }}</strong><small>{{ item.private?'私有':item.gated?'受限访问':'公开' }} · 下载 {{ item.downloads }}</small></button></div><button v-if="next" :disabled="busy" @click="search(true)">更多搜索结果</button><RouterLink to="/api-sources">管理 HF Bearer 凭据</RouterLink></aside>
 <div class="wb-stack"><section class="wb-panel wb-stack"><h2>固定来源与范围</h2><fieldset class="scenario-fieldset" :disabled="busy || !!pending"><form class="wb-form" @submit.prevent="inspect"><label>数据集仓库<input v-model="repo" required placeholder="组织/数据集" /></label><label>revision<input v-model="revision" required placeholder="main 或 40 位提交 SHA" /></label><label>访问凭据<select aria-label="访问凭据" v-model="credential"><option value="">匿名公开访问</option><option v-for="c in credentials" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><button type="submit">读取固定版本</button></form><button v-if="credentialNext" type="button" @click="loadCredentials(true)">更多凭据</button></fieldset><template v-if="dataset"><p class="wb-footnote">固定 revision：{{ dataset.revision }}<br />许可证：{{ dataset.license || '数据卡未提供，请核实使用授权' }}</p><details v-if="dataset.card"><summary>数据卡</summary><p class="scenario-report">{{ dataset.card }}</p></details><p v-for="warning in dataset.warnings" :key="warning" class="wb-footnote">{{ warning }}</p>
 <p v-if="!decoderReady" class="wb-footnote" role="status">解码服务尚未配置或状态读取失败。可以搜索和查看数据卡；预览与导入暂不可用。</p><fieldset class="scenario-fieldset" :disabled="busy || !!pending"><div class="wb-form"><label>配置<select aria-label="配置" v-model="config"><option value="">明确选择配置</option><option v-for="c in dataset.configs" :key="c.name">{{ c.name }}</option></select></label><label>数据切分<select aria-label="数据切分" v-model="split"><option value="">明确选择 split</option><option v-for="s in splits" :key="s.name">{{ s.name }}</option></select></label><label>最多导入行数<input v-model.number="maxRows" type="number" min="1" max="1000" /></label><label>下载预算（字节）<input v-model.number="maxBytes" type="number" min="1" max="16777216" /></label></div><p v-if="!dataset.configs.length" class="wb-footnote">数据卡没有可验证的 config / split 映射，当前不能导入；不会猜测切分。</p><div><h3>静态文件（最多 4 个）</h3><label v-for="file in files" :key="file.path" class="wb-checkbox"><input v-model="selectedFiles" type="checkbox" :value="file.path" :disabled="!file.supported" />{{ file.path }} · {{ file.size===null?'大小未知':`${file.size} 字节` }} · {{ file.supported?file.format:'不支持' }}</label></div>
 <label class="wb-label">导入字段方式<select aria-label="导入字段方式" v-model="mappingMode"><option value="text">文本 + 来源 ID</option><option value="columns">显式列映射（问答 / JSON / 特征数据）</option></select></label><div v-if="mappingMode==='text'" class="wb-form"><label>文本字段<input v-model="textField" placeholder="例如 utt，由你明确选择" /></label><label>ID 字段（可选）<input v-model="idField" placeholder="留空则从文件与行号派生" /></label></div><RecordEditor v-else v-model="columnMapping" title="导入列" :fields="mappingFields" /><p class="wb-footnote">只导入明确选择的字段。监督答案和原始标签不会自动加入；messages / tools 等嵌套字段需选择 JSON 编码。预览会列出被排除字段。</p><div class="wb-actions"><button type="button" :disabled="!decoderReady" @click="preview">预览选定字段</button><button class="primary" type="button" :disabled="!decoderReady || !previewed || previewKey!==requestKey" @click="importData">确认预览并导入</button></div></fieldset></template></section>
 <section v-if="pending" class="wb-panel"><h2>等待导入回执核对</h2><p class="scenario-wait">请求结果尚未确认。下方操作使用同一请求与幂等键核对，不更换输入、不自动重试下载。</p><button :disabled="busy" @click="importData">核对此次导入（相同请求）</button></section>
 <section v-if="previewed" class="wb-panel"><h2>导入预览</h2><p v-if="previewed.number_encoding==='exact_string'" class="wb-footnote">数值按精确原文展示；导入资产保留真实数值类型。</p><p class="wb-footnote">本次 {{ previewed.manifest.rows }} 行；预览 {{ previewed.rows.length }} 行。{{ previewed.manifest.sampled||previewed.manifest.truncated?'这是有界样本，并非完整数据集。':'仅代表已选文件与范围。' }}<br />源总行数：{{ previewed.manifest.total_rows===null?'未知':previewed.manifest.total_rows }}<br />排除字段：{{ previewed.manifest.excluded_columns?.join('、') || '无' }}</p><p class="wb-footnote">源字段（仅结构）：{{ previewed.source_columns.map(c=>`${c.name} (${c.type})`).join('、') }}</p><div class="wb-table-wrap"><table class="wb-table"><thead><tr><th v-for="c in previewed.columns" :key="c">{{ c }}</th></tr></thead><tbody><tr v-for="(row,i) in previewed.rows" :key="i"><td v-for="(cell,j) in row" :key="j">{{ typeof cell==='object'?JSON.stringify(cell):cell }}</td></tr></tbody></table></div></section>
 <section v-if="result" class="wb-panel wb-stack" aria-label="HF 导入结果"><div class="wb-section-head"><h2>导入结果</h2><span class="wb-badge">{{ state(result.status) }}</span><button :disabled="busy" @click="readImport(result.id)">刷新记录</button></div><RouterLink :to="{path:'/hf-datasets',query:{import_id:result.id}}">打开此导入记录链接</RouterLink><p class="wb-footnote">{{ result.id }} · {{ result.manifest?.revision }}</p><p v-if="result.error_code" class="wb-error">{{ result.error_code }}</p><p v-if="result.manifest">实际导入 {{ result.manifest.rows }} 行 · {{ result.manifest.bytes }} 字节 · {{ result.manifest.sampled||result.manifest.truncated?'有界样本':'选定文件范围' }}</p><div v-for="ref in result.output_refs" :key="`${ref.asset_id}:${ref.version}`" class="wb-actions"><RouterLink :to="{path:'/experts',query:{agent_id:'data-cleaning',asset:`${ref.asset_id}:${ref.version}`}}">清洗此资产</RouterLink><RouterLink :to="{path:'/analysis',query:{asset:`${ref.asset_id}:${ref.version}`}}">查看导入产物</RouterLink><RouterLink :to="{path:'/features',query:{source_ref:`${ref.asset_id}:${ref.version}`}}">特征工程</RouterLink></div></section></div></div></main>
</template>
<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {huggingfaceApi as api,type HFSearchItem,type HFDataset,type HFPreview,type HFImport,type HFRequest} from '@/api/scenario/huggingface'
import {apiSourceApi,type APICredential} from '@/api/apisource'
import RecordEditor,{type EditorField} from '@/components/workbench/RecordEditor.vue'
import ScenarioPath from './ScenarioPath.vue'
import {useScenarioSession} from './useScenarioSession'
import '@/components/workbench/workbench.css'
import './scenario.css'
const route=useRoute(),query=ref(''),results=ref<HFSearchItem[]>([]),next=ref(''),repo=ref(''),revision=ref('main'),credential=ref(''),credentials=ref<APICredential[]>([]),credentialNext=ref(''),dataset=ref<HFDataset>(),config=ref(''),split=ref(''),selectedFiles=ref<string[]>([]),maxRows=ref(100),maxBytes=ref(16777216),textField=ref(''),idField=ref(''),mappingMode=ref('text'),columnMapping=ref<Record<string,unknown>[]>([]),previewed=ref<HFPreview>(),previewKey=ref(''),result=ref<HFImport>(),pending=ref<HFRequest>(),decoderReady=ref(false)
const session=useScenarioSession(()=>{results.value=[];next.value='';credentials.value=[];credentialNext.value='';repo.value='';credential.value='';resetDataset();pending.value=undefined;result.value=undefined;decoderReady.value=false;void initialize()}),{busy,error,notice}=session
const splits=computed(()=>dataset.value?.configs.find(c=>c.name===config.value)?.splits||[])
const files=computed(()=>{const paths=splits.value.find(s=>s.name===split.value)?.files||[];return (dataset.value?.files||[]).filter(f=>paths.includes(f.path))})
const mappingFields:EditorField[]=[{key:'source',label:'源字段'},{key:'target',label:'目标字段'},{key:'encoding',label:'编码',options:[{value:'',label:'保留标量'},{value:'json',label:'JSON 字符串'}]}]
const request=computed<HFRequest>(()=>({repo_id:dataset.value?.repo_id||'',revision:dataset.value?.revision||'',config:config.value,split:split.value,files:[...selectedFiles.value],field_mapping:mappingMode.value==='text'?{text_field:textField.value.trim(),...(idField.value.trim()?{id_field:idField.value.trim()}:{})}:{columns:columnMapping.value.map(c=>({source:String(c.source||'').trim(),target:String(c.target||'').trim(),...(c.encoding==='json'?{encoding:'json' as const}:{})}))},max_rows:maxRows.value,max_bytes:maxBytes.value,...(credential.value?{credential_id:credential.value}:{})}))
const requestKey=computed(()=>JSON.stringify(request.value)),state=(s:string)=>({queued:'已排队',running:'导入中',cancel_requested:'已申请取消',cancelled:'已取消',timed_out:'已超时',succeeded:'已导入',failed:'导入失败'}[s]||s)
function resetDataset(){dataset.value=undefined;config.value='';split.value='';selectedFiles.value=[];previewed.value=undefined;previewKey.value='';textField.value='';idField.value='';columnMapping.value=[]}
watch(credential,()=>{results.value=[];next.value=''})
watch(query,()=>{results.value=[];next.value=''})
watch(config,()=>{split.value='';selectedFiles.value=[]});watch(split,()=>{selectedFiles.value=[]})
watch([repo,revision,credential],()=>{if(!pending.value){session.invalidate();resetDataset()}},{flush:'sync'})
function validatedRequest(){const r=request.value;if(!r.config||!r.split||!r.files.length||r.files.length>4||r.files.some(p=>!files.value.some(f=>f.path===p&&f.supported)))throw new Error('请选择配置、切分及 1–4 个支持的静态文件');if(!Number.isSafeInteger(r.max_rows)||r.max_rows<1||r.max_rows>1000||!Number.isSafeInteger(r.max_bytes)||r.max_bytes<1||r.max_bytes>16777216)throw new Error('行数与下载预算超出限制');if('text_field' in r.field_mapping?!r.field_mapping.text_field:!r.field_mapping.columns.length||r.field_mapping.columns.some(c=>!c.source||!c.target))throw new Error('请明确填写要导入的字段');return JSON.parse(JSON.stringify(r)) as HFRequest}
async function search(append=false){await session.run(async valid=>{const r=await api.search(query.value,append?next.value:'',credential.value||undefined);if(!valid())return;results.value=[...(append?results.value:[]),...(r.data?.items||[])];next.value=r.data?.next_cursor||''})}
async function choose(id:string){repo.value=id;await Promise.resolve();await inspect()}
async function inspect(){session.invalidate();resetDataset();await session.run(async valid=>{const r=await api.dataset(repo.value.trim(),revision.value.trim(),credential.value||undefined);if(valid())dataset.value=r.data})}
async function preview(){if(!decoderReady.value)return;await session.run(async valid=>{const data=validatedRequest(),key=JSON.stringify(data);const r=await api.preview(data);if(!valid()||key!==requestKey.value)return;previewed.value=r.data;previewKey.value=key})}
async function importData(){if(!decoderReady.value)return;await session.run(async valid=>{const data=pending.value||validatedRequest();if(!pending.value&&previewKey.value!==JSON.stringify(data))throw new Error('配置已改变，请重新预览');pending.value=data;const r=await api.import(data);if(!valid())return;if(!r.data)throw new Error('未收到导入回执，请显式核对此次请求');result.value=r.data;pending.value=undefined;notice.value='已读取真实导入回执。'})}
async function readImport(id:string){session.invalidate();result.value=undefined;await session.run(async valid=>{const r=await api.get(id);if(valid())result.value=r.data})}
async function loadCredentials(append=false){await session.run(async valid=>{const r=await apiSourceApi.credentials(append?credentialNext.value:'');if(!valid())return;credentials.value=[...(append?credentials.value:[]),...(r.data?.items||[])].filter(c=>c.enabled&&c.kind==='bearer'&&c.origin.replace(/\/$/,'')==='https://huggingface.co');credentialNext.value=r.data?.next_cursor||''})}
async function initialize(){const valid=session.capture();await session.run(async current=>{const r=await api.capabilities();if(current())decoderReady.value=r.data?.items.some(c=>c.id==='huggingface'&&c.decoder_ready&&c.fixed_revision_preview&&c.static_file_import)||false});if(!valid())return;await loadCredentials();if(valid()&&typeof route.query.import_id==='string')await readImport(route.query.import_id)}
watch(()=>route.query.import_id,id=>{if(typeof id==='string')void readImport(id)})
onMounted(initialize)
</script>
